	void retainedMatchingPrivateParameterKeepsItsSuppliedProvenance(Layout layout) {
		QueryEvaluationContext context = layout.context();
		MutableBindingSet original = GraphFrameBindings.supply(input(G2), PRIVATE, G1);
		original.setBinding(HIDDEN, VF.createLiteral("excluded"));
		BindingSet retained = FilterIterator.retainBindings(Set.of(PRIVATE), context).apply(original);
		assertThat(retained.getBindingNames()).containsExactly(PRIVATE);
		assertThat(retained.getValue(PRIVATE)).isEqualTo(G1);
		assertThat(retained.hasBinding(CALLER)).isFalse();
		assertThat(retained.hasBinding(HIDDEN)).isFalse();
		assertThat(GraphFrameBindings.isSupplied(retained, PRIVATE))
				.as("a condition input projection must preserve the authority of an included private graph")
				.isTrue();
		Projection projection = dependentProjection(Var.of(CALLER));
		assertThat(ProjectionQueryEvaluationStep.withInheritedGraphInput(projection, retained, context))
				.isSameAs(retained);
		assertThat(rows(projection, retained, context)).hasSize(1);
	}

