	@ParameterizedTest
	@EnumSource(Layout.class)
	void retainedOptimizationParameterKeepsOnlyPermittedRequestAuthority(Layout layout) {
		QueryEvaluationContext context = layout.context();
		MutableBindingSet entry = input(G1);
		entry.setBinding(HIDDEN, G2);
		BindingSet optimized = BindingSetOrigin.optimizationInput(entry);
		assertThat(optimized.isEmpty()).isTrue();
		assertThat(BindingSetOrigin.of(optimized).parameterValue(CALLER)).isEqualTo(G1);
		assertThat(BindingSetOrigin.of(optimized).parameterValue(HIDDEN)).isEqualTo(G2);
		BindingSet retained = FilterIterator.retainBindings(Set.of(CALLER), context).apply(optimized);
		assertThat(retained.isEmpty()).isTrue();
		assertThat(BindingSetOrigin.of(retained).isRequest(CALLER)).isTrue();
		assertThat(BindingSetOrigin.of(retained).parameterValue(CALLER)).isEqualTo(G1);
		assertThat(BindingSetOrigin.of(retained).isRequest(HIDDEN)).isFalse();
		assertThat(BindingSetOrigin.of(retained).parameterValue(HIDDEN)).isNull();
		BindingSet materialized = BindingSetOrigin.materializeParameters(retained,
				List.of(Var.of(CALLER, G1, false, false), Var.of(HIDDEN, G2, false, false)), context);
		assertThat(materialized.getValue(CALLER)).isEqualTo(G1);
		assertThat(materialized.hasBinding(HIDDEN)).isFalse();
	}

	@ParameterizedTest
	@EnumSource(Layout.class)
	void emptyRetainedFrameCannotReifyExcludedRequestParameters(Layout layout) {
		QueryEvaluationContext context = layout.context();
		BindingSet optimized = BindingSetOrigin.optimizationInput(input(G1));
		BindingSet excluded = FilterIterator.retainBindings(Set.of(), context).apply(optimized);
		assertThat(excluded.isEmpty()).isTrue();
		assertThat(BindingSetOrigin.of(excluded).parameterValue(CALLER)).isNull();
		assertThat(BindingSetOrigin.materializeParameters(excluded,
				List.of(Var.of(CALLER, G1, false, false)), context).hasBinding(CALLER)).isFalse();
		// A local definition masks an old request even when this condition permits that lexical name.
		BindingSet masked = BindingSetOrigin.produced(optimized, Set.of(CALLER));
		BindingSet retainedLocal = FilterIterator.retainBindings(Set.of(CALLER), context).apply(masked);
		assertThat(BindingSetOrigin.of(retainedLocal).parameterValue(CALLER)).isNull();
		assertThat(BindingSetOrigin.materializeParameters(retainedLocal,
				List.of(Var.of(CALLER, G1, false, false)), context).hasBinding(CALLER)).isFalse();
		// Scope projection does not rewrite an optimizer value or turn a term constant into a parameter.
		assertThat(BindingSetOrigin.materializeParameters(optimized,
				List.of(Var.of(CALLER, G1, false, true)), context).hasBinding(CALLER)).isFalse();
	}

	@Test
	void ordinaryNestedProjectionDistinguishesApiParametersFromLocalCompatibility() {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		Exists condition = independentLocalProjection();
		var prepared = strategy.precompile(condition, new QueryEvaluationContext.Minimal(null));
		assertThat(strategy.isTrue(prepared, BindingSetOrigin.requestInput(input(G1)))).isTrue();
		assertThat(strategy.isTrue(prepared, BindingSetOrigin.produced(input(G1), Set.of(CALLER)))).isFalse();
	}

