	private static Exists independentLocalProjection() {
		Extension local = new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(G2), CALLER));
		return new Exists(new Projection(local, new ProjectionElemList(new ProjectionElem(CALLER)), true));
	}

	@Test
	void metadataHeldVarSubclassIsActuallyReadByTheLoweringPath() {
		AtomicInteger nameReads = new AtomicInteger();
		Var context = new Var(CALLER) {
			@Override
			public String getName() {
				nameReads.incrementAndGet();
				return super.getName();
			}
		};
		Projection projection = dependentProjection(context);
		BindingSet lowered = ProjectionQueryEvaluationStep.withInheritedGraphInput(projection, input(G1),
				new QueryEvaluationContext.Minimal(null));
		assertThat(nameReads.get()).isPositive();
		assertThat(lowered.getValue(PRIVATE)).isEqualTo(G1);
		assertThat(GraphFrameBindings.isSupplied(lowered, PRIVATE)).isTrue();
	}

	private static Filter scopedFilter(TupleExpr input, Set<String> retained) {
		Filter filter = new Filter(input, new Exists(dependentProjection(Var.of(CALLER))));
		filter.setConditionBindingScope(ConditionBindingScope.retain(retained));
		return filter;
	}

	private static Projection dependentProjection(Var caller) {
		Filter guard = new Filter(new SingletonSet(), new SameTerm(Var.of(PRIVATE), new ValueConstant(G1)));
		// This is the projection's internal parameter consumer. The outer test FILTER separately owns its frame.
		guard.setConditionBindingScope(ConditionBindingScope.ALL);
		Projection projection = new Projection(guard, new ProjectionElemList(), true);
		projection.setProjectionContext(caller);
		projection.setInheritedGraphParameter(PRIVATE);
		return projection;
	}

	private static MutableBindingSet input(IRI graph) {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding(CALLER, graph);
		return input;
	}

	private static List<BindingSet> rows(TupleExpr expression, BindingSet input, QueryEvaluationContext context) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT);
		List<BindingSet> result = new ArrayList<>();
		try (var rows = strategy.precompile(expression.clone(), context).evaluate(input)) {
			while (rows.hasNext()) {
				result.add(new QueryBindingSet(rows.next()));
			}
		}
		return result;
	}

	private enum Layout {
		MAP,
		ARRAY,
		CUSTOM;

		QueryEvaluationContext context() {
			return switch (this) {
			case MAP -> new QueryEvaluationContext.Minimal(null);
			case ARRAY -> new ArrayBindingBasedQueryEvaluationContext(new QueryEvaluationContext.Minimal(null),
					new String[] { CALLER, PRIVATE, HIDDEN }, null);
			case CUSTOM -> new QueryEvaluationContext.Minimal(null) {
				@Override
				public MutableBindingSet createBindingSet() {
					return new MapBindingSet();
				}
			};
			};
		}
	}
